window.kbPageData["views/entry/k-b27ace94ee24b63f"] = {"key":"entry/k-b27ace94ee24b63f","state":{"route":"entry/k-b27ace94ee24b63f"},"node":{"id":"k-b27ace94ee24b63f","mode":"k","title":"党内监督体系","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["law","party"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"seeAlso":["k-fbdcaa4ff8744146"],"supplement":[{"doc":"41195a191a57c1c36332","file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf","first":20,"last":20,"relation":"制度依据","evidenceId":"8341faad4bf105a368b2","cardId":"d56b2b6974f5eb31","questionId":null,"basis":"机构注释","quote":"2.党内监督体系《中国共产党党内监督条例》规定：“建立健全党中央统一领导，党委（党组）全面监督，纪律检查机关专责监督，党的工作部门职能监督，党的基层组织日常监督，党员民主监督的党内监督体系。","text":"党中央统一领导；党委（党组）全面监督，纪律检查机关专责监督，党的工作部门职能监督，党的基层组织日常监督，党员民主监督。","reference":{"name":"中国共产党党内监督条例 · 第九条","url":"https://news.12371.cn/2016/11/02/ARTI1478087905680175.shtml"}}],"directorySummary":"党中央统一领导；党委（党组）全面监督，纪律检查机关专责监督，党的工作部门职能监督，党的基层组织日常监督，党员民主监督。","sources":[{"id":"d56b2b6974f5eb31","label":"党内监督体系","topic":"党政制度与理论","category":"非时政","text":"2.党内监督体系\n《中国共产党党内监督条例》规定：“建立健全党中央统一领导，党委（党组）\n全面监督，纪律检查机关专责监督，党的工作部门职能监督，党的基层组织日常监\n督，党员民主监督的党内监督体系。\n党中央集中统一领导：党内监督工作由党中央集中统一领导，各级党组织都要服从\n党中央领导。\n党委（党组）全面监督：党委（党组）在党内监督中负主体责任，由书记第一\n负责，统一领导本地区本部门本单位的党内监督工作。\n纪律检查机关专责监督：各级纪委是党内监督的专责机关，履行监督执纪问责\n职责。\n党的工作部门职能监督：党的工作部门是党委（党组）主体责任在不同领域的\n载体和抓手，党委办公厅、组织部、宣传部、统战部、政法委等工作部门，在职责\n范围内承担相应的监督职责。\n党的基层组织日常监督：基层党组织要通过组织生活等，对党员进行日常监督。\n党员民主监督：党员要行使监督权利，对领导干部和党的工作进行监督。","source":{"doc":"41195a191a57c1c36332","first":20,"last":20,"page":20,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{"k-fbdcaa4ff8744146":{"id":"k-fbdcaa4ff8744146","mode":"k","type":"制度与规则","title":"党和国家监督体系","qs":[],"count":0}},"references":{},"topics":[{"slug":"law","title":"法治政府与依法行政"},{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-b27ace94ee24b63f":[]}};
